  /**
   * @method
   * @name bybit#fetchClosedOrder
   * @description fetches information on a closed order made by the user
   * @see https://bybit-exchange.github.io/docs/v5/order/order-list
   * @param {string} id order id
   * @param {string} [symbol] unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.trigger] set to true for fetching a closed trigger
   * order
   * @param {boolean} [params.stop] alias for trigger
   * @param {string} [params.type] market type, ['swap', 'option', 'spot']
   * @param {string} [params.subType] market subType, ['linear', 'inverse']
   * @param {string} [params.orderFilter] 'Order' or 'StopOrder' or 'tpslOrder'
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  fetchClosedOrder(std::any id, std::any symbol = std::any{},
                   std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{
                     {std::string("orderId"), id},
                 };
                 std::any result = awaitValue(
                     this->fetchClosedOrders(symbol, std::any{}, std::any{},
                                             this->extend(request, params)));
                 std::any length = getArrayLength(result);
                 if (isTrue(isEqual(length, 0))) {
                   std::any isTrigger =
                       this->safeBool2(params, std::string("trigger"),
                                       std::string("stop"), false);
                   std::any extra =
                       (isTrue((isEqual(isTrigger, true)))
                            ? std::any(std::string(""))
                            : std::any(std::string(
                                  " If you are trying to fetch SL/TP "
                                  "conditional order, you might try setting "
                                  "params[\"trigger\"] = true")));
                   throw OrderNotFound(toString(
                       add(add(add(std::string("Order "), toString(id)),
                               std::string(" was not found.")),
                           extra)));
                 }
                 if (isTrue(isGreaterThan(length, 1))) {
                   throw InvalidOrder(toString(
                       add(this->id,
                           std::string(" returned more than one order"))));
                 }
                 return this->safeValue(result, 0);
               })
        .share();
  }

