                 //                     "cashBalance": "5086.56192602",
                 //                     "currency": "USDT",
                 //                     "category": "linear",
                 //                     "tradePrice": "0.3615",
                 //                     "tradeId":
                 //                     "5184f079-88ec-54c7-8774-5173cafd2b4e"
                 //                 },
                 //                 {
                 //                     "symbol": "XRPUSDT",
                 //                     "side": "Buy",
                 //                     "funding": "",
                 //                     "orderLinkId": "linear-order",
                 //                     "orderId":
                 //                     "592b7e41-78fd-42e2-9aa3-91e1835ef3e1",
                 //                     "fee": "0.00260280",
                 //                     "change": "-0.0026028",
                 //                     "cashFlow": "0",
                 //                     "transactionTime": "1672121182224",
                 //                     "type": "TRADE",
                 //                     "feeRate": "0.0006",
                 //                     "size": "12",
                 //                     "qty": "12",
                 //                     "cashBalance": "5086.58101322",
                 //                     "currency": "USDT",
