  virtual std::any parseSettlement(std::any settlement, std::any market) {
    //
    // fetchSettlementHistory
    //
    //     {
    //         "symbol": "SOL-27JUN23-20-C",
    //         "deliveryPrice": "16.62258889",
    //         "deliveryTime": "1687852800000"
    //     }
    //
    // fetchMySettlementHistory
    //
    //     {
    //         "symbol": "SOL-27JUN23-20-C",
    //         "deliveryPrice": "16.62258889",
    //         "deliveryTime": "1687852800000",
    //         "side": "Buy",
    //         "strike": "20",
    //         "fee": "0.00000000",
    //         "position": "0.01",
    //         "deliveryRpl": "3.5"
    //     }
    //
    std::any timestamp =
        this->safeInteger(settlement, std::string("deliveryTime"));
    std::any marketId = this->safeString(settlement, std::string("symbol"));
    return ccxt::dict{
        {std::string("info"), settlement},
        {std::string("symbol"), this->safeSymbol(marketId, market)},
        {std::string("price"),
         this->safeNumber(settlement, std::string("deliveryPrice"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
    };
  }

  virtual std::any parseSettlements(std::any settlements, std::any market) {
    //
    // fetchSettlementHistory
    //
    //     [
    //         {
    //             "symbol": "SOL-27JUN23-20-C",
    //             "deliveryPrice": "16.62258889",
    //             "deliveryTime": "1687852800000"
    //         }
    //     ]
    //
    // fetchMySettlementHistory
    //
    //     [
    //         {
    //             "symbol": "SOL-27JUN23-20-C",
    //             "deliveryPrice": "16.62258889",
    //             "deliveryTime": "1687852800000",
    //             "side": "Buy",
    //             "strike": "20",
    //             "fee": "0.00000000",
    //             "position": "0.01",
    //             "deliveryRpl": "3.5"
    //         }
    //     ]
    //
    std::any result = ccxt::list{};
    for (std::any i = 0; isLessThan(i, getArrayLength(settlements));
         postFixIncrement(i)) {
      arrayPush(result,
                this->parseSettlement(::getValue(settlements, i), market));
    }
    return result;
  }

  /**
   * @method
   * @name bybit#fetchVolatilityHistory
   * @description fetch the historical volatility of an option market based on
   * an underlying asset
   * @see https://bybit-exchange.github.io/docs/v5/market/iv
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.period] the period in days to fetch the volatility
   * for: 7,14,21,30,60,90,180,270
   * @returns {object[]} a list of [volatility history objects]{@link
   * https://docs.ccxt.com/?id=volatility-structure}
   */
  virtual std::shared_future<std::any>
  fetchVolatilityHistory(std::any code, std::any params = ccxt::dict{}) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = this->currency(code);
                        std::any request = ccxt::dict{
                            {std::string("category"), std::string("option")},
                            {std::string("baseCoin"),
                             ::getValue(currency, std::string("id"))},
                        };
                        std::any response = awaitValue(
                            this->publicGetV5MarketHistoricalVolatility(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "retCode": 0,
                        //         "retMsg": "SUCCESS",
                        //         "category": "option",
                        //         "result": [
                        //             {
                        //                 "period": 7,
                        //                 "value": "0.23854072",
                        //                 "time": "1690574400000"
                        //             }
                        //         ]
                        //     }
                        //
                        std::any volatility = this->safeList(
                            response, std::string("result"), ccxt::list{});
                        return this->parseVolatilityHistory(volatility);
                      })
        .share();
  }

  virtual std::any parseVolatilityHistory(std::any volatility) {
    //
    //     {
    //         "period": 7,
    //         "value": "0.23854072",
    //         "time": "1690574400000"
    //     }
    //
    std::any result = ccxt::list{};
    for (std::any i = 0; isLessThan(i, getArrayLength(volatility));
         postFixIncrement(i)) {
      std::any entry = ::getValue(volatility, i);
      std::any timestamp = this->safeInteger(entry, std::string("time"));
      arrayPush(result, ccxt::dict{
                            {std::string("info"), volatility},
                            {std::string("timestamp"), timestamp},
                            {std::string("datetime"), this->iso8601(timestamp)},
                            {std::string("volatility"),
                             this->safeNumber(entry, std::string("value"))},
                        });
    }
    return result;
  }

  /**
   * @method
   * @name bybit#fetchGreeks
   * @description fetches an option contracts greeks, financial metrics used to
   * measure the factors that affect the price of an options contract
   * @see https://bybit-exchange.github.io/docs/api-explorer/v5/market/tickers
   * @param {string} symbol unified symbol of the market to fetch greeks for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [greeks structure]{@link
   * https://docs.ccxt.com/?id=greeks-structure}
   */
  std::shared_future<std::any>
  fetchGreeks(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("category"), std::string("option")},
                 };
                 std::any response = awaitValue(this->publicGetV5MarketTickers(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "retCode": 0,
                 //         "retMsg": "SUCCESS",
                 //         "result": {
                 //             "category": "option",
                 //             "list": [
                 //                 {
                 //                     "symbol": "BTC-26JAN24-39000-C",
                 //                     "bid1Price": "3205",
                 //                     "bid1Size": "7.1",
                 //                     "bid1Iv": "0.5478",
                 //                     "ask1Price": "3315",
                 //                     "ask1Size": "1.98",
                 //                     "ask1Iv": "0.5638",
                 //                     "lastPrice": "3230",
                 //                     "highPrice24h": "3255",
                 //                     "lowPrice24h": "3200",
                 //                     "markPrice": "3273.02263032",
                 //                     "indexPrice": "36790.96",
                 //                     "markIv": "0.5577",
                 //                     "underlyingPrice": "37649.67254894",
                 //                     "openInterest": "19.67",
                 //                     "turnover24h": "170140.33875912",
                 //                     "volume24h": "4.56",
                 //                     "totalVolume": "22",
                 //                     "totalTurnover": "789305",
                 //                     "delta": "0.49640971",
                 //                     "gamma": "0.00004131",
                 //                     "vega": "69.08651675",
                 //                     "theta": "-24.9443226",
                 //                     "predictedDeliveryPrice": "0",
                 //                     "change24h": "0.18532111"
                 //                 }
                 //             ]
                 //         },
                 //         "retExtInfo": {},
                 //         "time": 1699584008326
                 //     }
                 //
                 std::any timestamp =
                     this->safeInteger(response, std::string("time"));
                 std::any result = this->safeDict(
                     response, std::string("result"), ccxt::dict{});
                 std::any data =
                     this->safeList(result, std::string("list"), ccxt::list{});
                 std::any greeks =
                     this->parseGreeks(::getValue(data, 0), market);
                 return this->extend(
                     greeks,
                     ccxt::dict{
                         {std::string("timestamp"), timestamp},
                         {std::string("datetime"), this->iso8601(timestamp)},
                     });
               })
        .share();
  }

